      "@type": "Question",
      "name": "Why do small wins matter in machine knitting?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Small wins help you build confidence through action. Each success reinforces your skills and makes larger projects feel more approachable."
      }
    },
    {
      "@type": "Question",
      "name": "How does Knit by Machine support small wins?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Every workshop, wizard, and ANA entry is designed to give you one clear, achievable step. You always know exactly what to do next."
      }
    },
    {
      "@type": "Question",
      "name": "What’s an example of a small win I can focus on?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It might be a clean cast-on, finishing your first simple shape, or creating a small gift like a baby blanket. Any step that feels achievable counts as a win."
      }
    }
  ]
